int fd = open("sparse", O_CREAT | O_WRONLY, 0644);
lseek(fd, 1048576, SEEK_SET);
write(fd, "x", 1);
close(fd);
/* ls -l sparse -> 1048577 bytes; du -k sparse -> 4 */

